  bolt:'<path d="m13 2-8 12h6l-1 8 9-13h-7l1-7Z"/>',
  chevron:'<path d="m9 5 7 7-7 7"/>', down:'<path d="m6 9 6 6 6-6"/>',
  arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>', check:'<path d="m5 12 4 4L19 6"/>',
