  chart:'<path d="M3 3v18h18M7 15v3M12 10v8M17 6v12"/>',
  user:'<circle cx="12" cy="8" r="4"/><path d="M4 21v-2a8 8 0 0 1 16 0v2"/>',
  truck:'<path d="M3 6h12v11H3V6Zm12 5h4l3 4v2h-7"/><circle cx="7" cy="18" r="2"/><circle cx="18" cy="18" r="2"/>',
